package com.careerpilot.modules.assessment.mapper;

import com.careerpilot.modules.assessment.dto.*;import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.assessment.service.AttemptQuestionSet;import org.springframework.stereotype.Component;import java.util.*;
@Component
public class AssessmentMapper{
 private final AttemptQuestionSet questionSet;public AssessmentMapper(AttemptQuestionSet questionSet){this.questionSet=questionSet;}
 public AssessmentSummaryResponse summary(Assessment a){return new AssessmentSummaryResponse(a.getId(),a.getTitle(),a.getDescription(),a.getAssessmentType(),a.getTargetRole(),a.getDifficulty(),a.getDurationMinutes(),a.getTotalQuestions(),a.getPassingPercentage(),a.getCatalogGroup());}
 public AssessmentDetailResponse detail(Assessment a){return new AssessmentDetailResponse(summary(a),questions(a),"Select one answer per question. Grading and expiry are enforced by the server. Correct answers and explanations are revealed only after submission.");}
 public QuestionResponse question(AssessmentQuestion q){return new QuestionResponse(q.getId(),q.getQuestionOrder(),q.getQuestionType(),q.getQuestionText(),q.getDifficulty(),q.getSkillTag(),q.getOptions().stream().map(o->new OptionResponse(o.getOptionKey(),o.getOptionText())).toList());}
 private QuestionResponse question(AssessmentQuestion q,int order){return new QuestionResponse(q.getId(),order,q.getQuestionType(),q.getQuestionText(),q.getDifficulty(),q.getSkillTag(),q.getOptions().stream().map(o->new OptionResponse(o.getOptionKey(),o.getOptionText())).toList());}
 public List<QuestionResponse>questions(Assessment a){return a.getQuestions().stream().map(this::question).toList();}
 public AttemptSummaryResponse attemptSummary(AssessmentAttempt a){return new AttemptSummaryResponse(a.getId(),a.getAssessment().getId(),a.getAssessment().getTitle(),a.getStatus(),a.getStartedAt(),a.getSubmittedAt(),a.getScorePercentage(),a.getScorePercentage()==null?null:a.getScorePercentage()>=a.getAssessment().getPassingPercentage(),a.getDurationSeconds());}
 public AttemptResponse attempt(AssessmentAttempt a){boolean submitted=a.getStatus()==AttemptStatus.SUBMITTED;List<AttemptQuestionResult>results=submitted?results(a):List.of();List<BreakdownResponse>skills=submitted?breakdown(results,true):List.of(),difficulty=submitted?breakdown(results,false):List.of();String strongest=topic(skills,true),weakest=topic(skills,false);List<AssessmentQuestion>selected=questionSet.resolve(a);List<QuestionResponse>questions=new ArrayList<>();for(int i=0;i<selected.size();i++)questions.add(question(selected.get(i),i+1));return new AttemptResponse(a.getId(),summary(a.getAssessment()),a.getStatus(),a.getStartedAt(),a.getStartedAt().plusSeconds(a.getAssessment().getDurationMinutes()*60L),a.getSubmittedAt(),a.getScorePercentage(),a.getScorePercentage()==null?null:a.getScorePercentage()>=a.getAssessment().getPassingPercentage(),a.getCorrectAnswers(),a.getIncorrectAnswers(),a.getUnanswered(),a.getTotalQuestions(),a.getDurationSeconds(),a.getStatus()==AttemptStatus.IN_PROGRESS?List.copyOf(questions):List.of(),results,skills,difficulty,strongest,weakest);}
 private List<AttemptQuestionResult>results(AssessmentAttempt a){Map<UUID,AssessmentAnswer>answers=new HashMap<>();a.getAnswers().forEach(v->answers.put(v.getQuestion().getId(),v));List<AssessmentQuestion>selected=questionSet.resolve(a);Map<UUID,Integer>orders=new HashMap<>();for(int i=0;i<selected.size();i++)orders.put(selected.get(i).getId(),i+1);return selected.stream().map(q->{AssessmentAnswer answer=answers.get(q.getId());AssessmentOption selectedOption=answer==null?null:q.getOptions().stream().filter(o->o.getOptionKey().equals(answer.getSelectedOptionKey())).findFirst().orElse(null);AssessmentOption correct=q.getOptions().stream().filter(AssessmentOption::isCorrect).findFirst().orElseThrow();return new AttemptQuestionResult(q.getId(),orders.get(q.getId()),q.getQuestionText(),answer==null?null:answer.getSelectedOptionKey(),selectedOption==null?null:selectedOption.getOptionText(),correct.getOptionKey(),correct.getOptionText(),q.getExplanation(),q.getSkillTag(),q.getDifficulty(),answer==null?null:answer.getCorrect());}).toList();}
 private List<BreakdownResponse>breakdown(List<AttemptQuestionResult>results,boolean skill){Map<String,int[]>map=new TreeMap<>();for(var r:results){String label=skill?(r.skillTag()==null||r.skillTag().isBlank()?"General":r.skillTag()):r.difficulty().name();int[]v=map.computeIfAbsent(label,k->new int[2]);v[1]++;if(Boolean.TRUE.equals(r.correct()))v[0]++;}return map.entrySet().stream().map(e->new BreakdownResponse(e.getKey(),e.getValue()[0],e.getValue()[1],(int)Math.round(e.getValue()[0]*100.0/e.getValue()[1]))).toList();}
 private String topic(List<BreakdownResponse>values,boolean strongest){if(values.isEmpty()||(strongest&&values.stream().noneMatch(value->value.percentage()>0)))return null;Comparator<BreakdownResponse>comparator=Comparator.comparingInt(BreakdownResponse::percentage).thenComparing(BreakdownResponse::label);return (strongest?values.stream().max(comparator):values.stream().min(comparator)).map(BreakdownResponse::label).orElse(null);}
}
